-- Nile Analytics Labs: SPSS for Data Analysis
-- Run after lms_schema.sql, seed_excel_course.sql and quizzes_and_demo_learners.sql.
-- This course is intentionally unpublished until reviewed by an administrator.

create unique index if not exists course_modules_course_order_uidx on public.course_modules(course_id, sort_order);
create unique index if not exists lessons_module_order_uidx on public.lessons(module_id, sort_order);

insert into public.courses(title,slug,category,description,level,duration,is_published)
values ('SPSS for Data Analysis','spss-for-data-analysis','SPSS',
'Develop practical SPSS skills for importing, cleaning, describing and analysing survey and research data.',
'Beginner to Intermediate','8 weeks',false)
on conflict(slug) do update set title=excluded.title,category=excluded.category,description=excluded.description,level=excluded.level,duration=excluded.duration,updated_at=now();

do $$
declare v_course uuid; v_module uuid;
begin
 select id into v_course from public.courses where slug='spss-for-data-analysis';
 for v_module in select id from public.course_modules where course_id=v_course loop
   null;
 end loop;
 insert into public.course_modules(course_id,title,description,sort_order) values(v_course,'SPSS Foundations and Research Workflow','Understand SPSS, the interface, research data structures and a reproducible analysis workflow.',1) on conflict(course_id,sort_order) do update set title=excluded.title,description=excluded.description;
 insert into public.course_modules(course_id,title,description,sort_order) values(v_course,'Data Entry, Importing and Variable Setup','Create and import datasets, define variable properties, labels, value codes and measurement levels.',2) on conflict(course_id,sort_order) do update set title=excluded.title,description=excluded.description;
 insert into public.course_modules(course_id,title,description,sort_order) values(v_course,'Data Cleaning and Data Quality','Detect missing values, duplicates, invalid codes and outliers using documented cleaning decisions.',3) on conflict(course_id,sort_order) do update set title=excluded.title,description=excluded.description;
 insert into public.course_modules(course_id,title,description,sort_order) values(v_course,'Descriptive Statistics and Data Exploration','Use frequencies, descriptive summaries, crosstabs and charts to describe survey and education data.',4) on conflict(course_id,sort_order) do update set title=excluded.title,description=excluded.description;
 insert into public.course_modules(course_id,title,description,sort_order) values(v_course,'Data Transformation and Management','Recode variables, compute new fields, select cases, sort, split files and merge datasets.',5) on conflict(course_id,sort_order) do update set title=excluded.title,description=excluded.description;
 insert into public.course_modules(course_id,title,description,sort_order) values(v_course,'Inferential Statistics and Hypothesis Testing','Apply chi-square, t-tests, ANOVA and correlation while checking assumptions and interpreting results.',6) on conflict(course_id,sort_order) do update set title=excluded.title,description=excluded.description;
 insert into public.course_modules(course_id,title,description,sort_order) values(v_course,'Regression and Advanced Analysis','Run linear and logistic regression, interpret coefficients and assess model fit and limitations.',7) on conflict(course_id,sort_order) do update set title=excluded.title,description=excluded.description;
 insert into public.course_modules(course_id,title,description,sort_order) values(v_course,'Research Reporting and Applied SPSS Project','Export tables and charts, write reproducible syntax and complete an applied research analysis.',8) on conflict(course_id,sort_order) do update set title=excluded.title,description=excluded.description;
 insert into public.lessons(module_id,title,content,video_url,resource_url,duration_minutes,sort_order,is_published) select id,'What SPSS is and when to use it','IBM SPSS Statistics is software for data management and statistical analysis. It is commonly used for survey research, programme monitoring and social science datasets. Start with a research question, define the population and unit of analysis, and identify variables before opening the software.',null,'https://www.ibm.com/products/spss-statistics',25,1,true from public.course_modules where course_id=v_course and sort_order=1 on conflict(module_id,sort_order) do update set title=excluded.title,content=excluded.content,resource_url=excluded.resource_url,duration_minutes=excluded.duration_minutes,is_published=true;
 insert into public.lessons(module_id,title,content,video_url,resource_url,duration_minutes,sort_order,is_published) select id,'Tour of the SPSS interface','Explore the Data Editor, Variable View, Output Viewer and Syntax Editor. Learn how Data View displays cases and Variable View describes fields. Open a sample dataset, switch between views and identify where output tables and charts appear.',null,'https://www.ibm.com/docs/en/spss-statistics',25,2,true from public.course_modules where course_id=v_course and sort_order=1 on conflict(module_id,sort_order) do update set title=excluded.title,content=excluded.content,resource_url=excluded.resource_url,duration_minutes=excluded.duration_minutes,is_published=true;
 insert into public.lessons(module_id,title,content,video_url,resource_url,duration_minutes,sort_order,is_published) select id,'Cases, variables and measurement levels','A case is an observation, often one respondent or learner; a variable is a measured attribute. Distinguish nominal, ordinal and scale measurement levels. Assign the correct level because it influences available summaries, charts and statistical procedures.',null,'https://www.ibm.com/docs/en/spss-statistics',25,3,true from public.course_modules where course_id=v_course and sort_order=1 on conflict(module_id,sort_order) do update set title=excluded.title,content=excluded.content,resource_url=excluded.resource_url,duration_minutes=excluded.duration_minutes,is_published=true;
 insert into public.lessons(module_id,title,content,video_url,resource_url,duration_minutes,sort_order,is_published) select id,'Build a research data dictionary','Create a data dictionary with variable name, label, type, units, allowed values, missing-value rules and measurement level. Use short, consistent names and document every coding decision. A data dictionary makes datasets understandable to collaborators.',null,'https://www.ibm.com/docs/en/spss-statistics',25,4,true from public.course_modules where course_id=v_course and sort_order=1 on conflict(module_id,sort_order) do update set title=excluded.title,content=excluded.content,resource_url=excluded.resource_url,duration_minutes=excluded.duration_minutes,is_published=true;
 insert into public.lessons(module_id,title,content,video_url,resource_url,duration_minutes,sort_order,is_published) select id,'Save projects and use SPSS syntax','Save data files as .sav and save analysis commands in syntax files. Use Paste rather than only clicking OK in dialog boxes to capture commands. Rerun syntax from a clean session and retain a read-only copy of original data.',null,'https://www.ibm.com/docs/en/spss-statistics',30,5,true from public.course_modules where course_id=v_course and sort_order=1 on conflict(module_id,sort_order) do update set title=excluded.title,content=excluded.content,resource_url=excluded.resource_url,duration_minutes=excluded.duration_minutes,is_published=true;
 insert into public.lessons(module_id,title,content,video_url,resource_url,duration_minutes,sort_order,is_published) select id,'Create a new dataset in Data View','Enter a small practice dataset with one row per respondent and one column per variable. Avoid merged cells, totals rows and multiple values in one cell. Save a working copy and verify the number of cases and variables.',null,'https://www.ibm.com/docs/en/spss-statistics',25,1,true from public.course_modules where course_id=v_course and sort_order=2 on conflict(module_id,sort_order) do update set title=excluded.title,content=excluded.content,resource_url=excluded.resource_url,duration_minutes=excluded.duration_minutes,is_published=true;
 insert into public.lessons(module_id,title,content,video_url,resource_url,duration_minutes,sort_order,is_published) select id,'Define names, types and labels in Variable View','Set variable names, numeric or string types, display widths and descriptive labels. Use labels to make output readable while keeping names concise. Check that imported numeric fields have not been read as text.',null,'https://www.ibm.com/docs/en/spss-statistics',25,2,true from public.course_modules where course_id=v_course and sort_order=2 on conflict(module_id,sort_order) do update set title=excluded.title,content=excluded.content,resource_url=excluded.resource_url,duration_minutes=excluded.duration_minutes,is_published=true;
 insert into public.lessons(module_id,title,content,video_url,resource_url,duration_minutes,sort_order,is_published) select id,'Value labels and user-missing values','Assign value labels to coded categories such as 1=Female and 2=Male only when those codes match the study instrument. Define user-missing codes deliberately and distinguish them from valid zeros or not-applicable responses.',null,'https://www.ibm.com/docs/en/spss-statistics',25,3,true from public.course_modules where course_id=v_course and sort_order=2 on conflict(module_id,sort_order) do update set title=excluded.title,content=excluded.content,resource_url=excluded.resource_url,duration_minutes=excluded.duration_minutes,is_published=true;
 insert into public.lessons(module_id,title,content,video_url,resource_url,duration_minutes,sort_order,is_published) select id,'Import CSV and Excel files','Use File > Import Data or the Text/Excel import wizard. Confirm headers, delimiters, decimal symbols, sheet selection and variable types. Compare imported row counts with the source and inspect several records for parsing errors.',null,'https://www.ibm.com/docs/en/spss-statistics',25,4,true from public.course_modules where course_id=v_course and sort_order=2 on conflict(module_id,sort_order) do update set title=excluded.title,content=excluded.content,resource_url=excluded.resource_url,duration_minutes=excluded.duration_minutes,is_published=true;
 insert into public.lessons(module_id,title,content,video_url,resource_url,duration_minutes,sort_order,is_published) select id,'Measure level, dates and category coding','Set nominal, ordinal or scale measurement correctly. Convert date strings using explicit formats and review category codes against the questionnaire. Create an import checklist and record any recoding required before analysis.',null,'https://www.ibm.com/docs/en/spss-statistics',30,5,true from public.course_modules where course_id=v_course and sort_order=2 on conflict(module_id,sort_order) do update set title=excluded.title,content=excluded.content,resource_url=excluded.resource_url,duration_minutes=excluded.duration_minutes,is_published=true;
 insert into public.lessons(module_id,title,content,video_url,resource_url,duration_minutes,sort_order,is_published) select id,'Profile missing values','Use Frequencies and Descriptives to count missing values by variable. Determine whether missingness means unknown, refused, not applicable or not collected. Report the denominator used in each analysis and avoid replacing blanks with zero without justification.',null,'https://www.ibm.com/docs/en/spss-statistics',25,1,true from public.course_modules where course_id=v_course and sort_order=3 on conflict(module_id,sort_order) do update set title=excluded.title,content=excluded.content,resource_url=excluded.resource_url,duration_minutes=excluded.duration_minutes,is_published=true;
 insert into public.lessons(module_id,title,content,video_url,resource_url,duration_minutes,sort_order,is_published) select id,'Find duplicate cases and identifiers','Use Identify Duplicate Cases and inspect the key fields. Establish whether the repeated rows are data-entry duplicates or legitimate repeated measurements. Preserve the source and document the rule before removing or flagging records.',null,'https://www.ibm.com/docs/en/spss-statistics',25,2,true from public.course_modules where course_id=v_course and sort_order=3 on conflict(module_id,sort_order) do update set title=excluded.title,content=excluded.content,resource_url=excluded.resource_url,duration_minutes=excluded.duration_minutes,is_published=true;
 insert into public.lessons(module_id,title,content,video_url,resource_url,duration_minutes,sort_order,is_published) select id,'Validate ranges and impossible values','Check minimums, maximums and frequency tables for impossible ages, scores outside the assessment scale and attendance exceeding enrolled days. Investigate flagged values against source records rather than automatically deleting them.',null,'https://www.ibm.com/docs/en/spss-statistics',25,3,true from public.course_modules where course_id=v_course and sort_order=3 on conflict(module_id,sort_order) do update set title=excluded.title,content=excluded.content,resource_url=excluded.resource_url,duration_minutes=excluded.duration_minutes,is_published=true;
 insert into public.lessons(module_id,title,content,video_url,resource_url,duration_minutes,sort_order,is_published) select id,'Recode inconsistent categories','Use Recode into Different Variables to harmonise spelling, case and category codes. Keep the original field for auditability, define value labels for the cleaned field and compare frequency distributions before and after recoding.',null,'https://www.ibm.com/docs/en/spss-statistics',25,4,true from public.course_modules where course_id=v_course and sort_order=3 on conflict(module_id,sort_order) do update set title=excluded.title,content=excluded.content,resource_url=excluded.resource_url,duration_minutes=excluded.duration_minutes,is_published=true;
 insert into public.lessons(module_id,title,content,video_url,resource_url,duration_minutes,sort_order,is_published) select id,'Create a documented cleaning log','Record the source file, checks performed, issues found, decisions, records affected and unresolved limitations. Save cleaned data separately from raw data and rerun the cleaning syntax to confirm the same result.',null,'https://www.ibm.com/docs/en/spss-statistics',30,5,true from public.course_modules where course_id=v_course and sort_order=3 on conflict(module_id,sort_order) do update set title=excluded.title,content=excluded.content,resource_url=excluded.resource_url,duration_minutes=excluded.duration_minutes,is_published=true;
 insert into public.lessons(module_id,title,content,video_url,resource_url,duration_minutes,sort_order,is_published) select id,'Frequency tables for categorical variables','Use Analyze > Descriptive Statistics > Frequencies to summarise gender, county, grade or programme status. Request counts and percentages, inspect valid and missing totals, and choose chart options that suit the variable.',null,'https://www.ibm.com/docs/en/spss-statistics',25,1,true from public.course_modules where course_id=v_course and sort_order=4 on conflict(module_id,sort_order) do update set title=excluded.title,content=excluded.content,resource_url=excluded.resource_url,duration_minutes=excluded.duration_minutes,is_published=true;
 insert into public.lessons(module_id,title,content,video_url,resource_url,duration_minutes,sort_order,is_published) select id,'Means, medians and dispersion','Use Descriptives and Explore to calculate mean, median, standard deviation, range and quartiles. Select statistics based on the distribution and measurement level. State units and sample sizes when reporting results.',null,'https://www.ibm.com/docs/en/spss-statistics',25,2,true from public.course_modules where course_id=v_course and sort_order=4 on conflict(module_id,sort_order) do update set title=excluded.title,content=excluded.content,resource_url=excluded.resource_url,duration_minutes=excluded.duration_minutes,is_published=true;
 insert into public.lessons(module_id,title,content,video_url,resource_url,duration_minutes,sort_order,is_published) select id,'Cross-tabulations and row percentages','Use Crosstabs to examine relationships between categorical variables. Choose row, column or total percentages according to the research question. Check expected counts before interpreting a chi-square test.',null,'https://www.ibm.com/docs/en/spss-statistics',25,3,true from public.course_modules where course_id=v_course and sort_order=4 on conflict(module_id,sort_order) do update set title=excluded.title,content=excluded.content,resource_url=excluded.resource_url,duration_minutes=excluded.duration_minutes,is_published=true;
 insert into public.lessons(module_id,title,content,video_url,resource_url,duration_minutes,sort_order,is_published) select id,'Explore distributions and outliers','Use Explore, histograms, boxplots and normal Q-Q plots to understand numeric distributions. Identify unusual values and skewness, but investigate records before deciding whether they are errors or valid extremes.',null,'https://www.ibm.com/docs/en/spss-statistics',25,4,true from public.course_modules where course_id=v_course and sort_order=4 on conflict(module_id,sort_order) do update set title=excluded.title,content=excluded.content,resource_url=excluded.resource_url,duration_minutes=excluded.duration_minutes,is_published=true;
 insert into public.lessons(module_id,title,content,video_url,resource_url,duration_minutes,sort_order,is_published) select id,'Choose charts for research questions','Create bar charts for categories, histograms for numeric distributions, boxplots for group comparisons and scatterplots for relationships. Use clear titles, axis labels and units; avoid misleading scales and unnecessary decoration.',null,'https://www.ibm.com/docs/en/spss-statistics',30,5,true from public.course_modules where course_id=v_course and sort_order=4 on conflict(module_id,sort_order) do update set title=excluded.title,content=excluded.content,resource_url=excluded.resource_url,duration_minutes=excluded.duration_minutes,is_published=true;
 insert into public.lessons(module_id,title,content,video_url,resource_url,duration_minutes,sort_order,is_published) select id,'Compute new variables','Use Transform > Compute Variable to calculate attendance percentages, age bands or total scores. Write the formula clearly, handle missing denominators and validate computed values against a few manually checked cases.',null,'https://www.ibm.com/docs/en/spss-statistics',25,1,true from public.course_modules where course_id=v_course and sort_order=5 on conflict(module_id,sort_order) do update set title=excluded.title,content=excluded.content,resource_url=excluded.resource_url,duration_minutes=excluded.duration_minutes,is_published=true;
 insert into public.lessons(module_id,title,content,video_url,resource_url,duration_minutes,sort_order,is_published) select id,'Recode into same or different variables','Use Recode to group continuous values or harmonise category codes. Prefer a new variable when preserving source values matters. Add value labels and verify that every original category maps to the intended result.',null,'https://www.ibm.com/docs/en/spss-statistics',25,2,true from public.course_modules where course_id=v_course and sort_order=5 on conflict(module_id,sort_order) do update set title=excluded.title,content=excluded.content,resource_url=excluded.resource_url,duration_minutes=excluded.duration_minutes,is_published=true;
 insert into public.lessons(module_id,title,content,video_url,resource_url,duration_minutes,sort_order,is_published) select id,'Select cases and filter records','Use Select Cases to analyse a defined subgroup, such as one grade or county. Understand filter versus delete behaviour, label the selection rule and restore all cases before producing whole-sample results.',null,'https://www.ibm.com/docs/en/spss-statistics',25,3,true from public.course_modules where course_id=v_course and sort_order=5 on conflict(module_id,sort_order) do update set title=excluded.title,content=excluded.content,resource_url=excluded.resource_url,duration_minutes=excluded.duration_minutes,is_published=true;
 insert into public.lessons(module_id,title,content,video_url,resource_url,duration_minutes,sort_order,is_published) select id,'Sort cases, split files and weight cases','Sort records by key variables, use Split File for group-specific output and understand when weighting is justified by the sampling design. Record settings because active split or weight options can affect later procedures.',null,'https://www.ibm.com/docs/en/spss-statistics',25,4,true from public.course_modules where course_id=v_course and sort_order=5 on conflict(module_id,sort_order) do update set title=excluded.title,content=excluded.content,resource_url=excluded.resource_url,duration_minutes=excluded.duration_minutes,is_published=true;
 insert into public.lessons(module_id,title,content,video_url,resource_url,duration_minutes,sort_order,is_published) select id,'Merge files and aggregate data','Add cases from compatible files or add variables using a verified key. Check key uniqueness, variable definitions and row counts before and after merging. Use Aggregate to create group-level summaries without confusing them with respondent-level records.',null,'https://www.ibm.com/docs/en/spss-statistics',30,5,true from public.course_modules where course_id=v_course and sort_order=5 on conflict(module_id,sort_order) do update set title=excluded.title,content=excluded.content,resource_url=excluded.resource_url,duration_minutes=excluded.duration_minutes,is_published=true;
 insert into public.lessons(module_id,title,content,video_url,resource_url,duration_minutes,sort_order,is_published) select id,'Statistical hypotheses and assumptions','Translate a research question into null and alternative hypotheses. Select tests based on variable types, study design and assumptions. Statistical significance is not the same as practical importance or proof of causality.',null,'https://www.ibm.com/docs/en/spss-statistics',25,1,true from public.course_modules where course_id=v_course and sort_order=6 on conflict(module_id,sort_order) do update set title=excluded.title,content=excluded.content,resource_url=excluded.resource_url,duration_minutes=excluded.duration_minutes,is_published=true;
 insert into public.lessons(module_id,title,content,video_url,resource_url,duration_minutes,sort_order,is_published) select id,'Chi-square test of independence','Use Crosstabs with Chi-square to test association between categorical variables. Review expected cell counts and consider exact or alternative methods when assumptions are not met. Report the test statistic, degrees of freedom and p-value.',null,'https://www.ibm.com/docs/en/spss-statistics',25,2,true from public.course_modules where course_id=v_course and sort_order=6 on conflict(module_id,sort_order) do update set title=excluded.title,content=excluded.content,resource_url=excluded.resource_url,duration_minutes=excluded.duration_minutes,is_published=true;
 insert into public.lessons(module_id,title,content,video_url,resource_url,duration_minutes,sort_order,is_published) select id,'Independent and paired-samples t-tests','Use an independent t-test for two unrelated groups and a paired t-test for repeated measurements on the same units. Check distributional assumptions and report group summaries, mean difference, confidence interval and p-value.',null,'https://www.ibm.com/docs/en/spss-statistics',25,3,true from public.course_modules where course_id=v_course and sort_order=6 on conflict(module_id,sort_order) do update set title=excluded.title,content=excluded.content,resource_url=excluded.resource_url,duration_minutes=excluded.duration_minutes,is_published=true;
 insert into public.lessons(module_id,title,content,video_url,resource_url,duration_minutes,sort_order,is_published) select id,'One-way ANOVA and post-hoc comparisons','Use One-Way ANOVA to compare means across three or more independent groups. Check variance assumptions and use suitable post-hoc comparisons. Explain which groups differ and report effect size where available.',null,'https://www.ibm.com/docs/en/spss-statistics',25,4,true from public.course_modules where course_id=v_course and sort_order=6 on conflict(module_id,sort_order) do update set title=excluded.title,content=excluded.content,resource_url=excluded.resource_url,duration_minutes=excluded.duration_minutes,is_published=true;
 insert into public.lessons(module_id,title,content,video_url,resource_url,duration_minutes,sort_order,is_published) select id,'Correlation and non-parametric alternatives','Use Pearson correlation for suitable linear relationships between scale variables and Spearman correlation for ranked or monotonic relationships. Inspect scatterplots and outliers; correlation does not establish causation.',null,'https://www.ibm.com/docs/en/spss-statistics',30,5,true from public.course_modules where course_id=v_course and sort_order=6 on conflict(module_id,sort_order) do update set title=excluded.title,content=excluded.content,resource_url=excluded.resource_url,duration_minutes=excluded.duration_minutes,is_published=true;
 insert into public.lessons(module_id,title,content,video_url,resource_url,duration_minutes,sort_order,is_published) select id,'Simple and multiple linear regression','Fit linear regression for a continuous outcome and explain predictors, coefficients and confidence intervals. Check linearity, residual patterns, independence and influential cases before relying on model estimates.',null,'https://www.ibm.com/docs/en/spss-statistics',25,1,true from public.course_modules where course_id=v_course and sort_order=7 on conflict(module_id,sort_order) do update set title=excluded.title,content=excluded.content,resource_url=excluded.resource_url,duration_minutes=excluded.duration_minutes,is_published=true;
 insert into public.lessons(module_id,title,content,video_url,resource_url,duration_minutes,sort_order,is_published) select id,'Regression diagnostics and model fit','Review R-squared, adjusted R-squared, residual plots, collinearity statistics and influential observations. Avoid selecting a model only because it produces a small p-value; relate diagnostics to the study design.',null,'https://www.ibm.com/docs/en/spss-statistics',25,2,true from public.course_modules where course_id=v_course and sort_order=7 on conflict(module_id,sort_order) do update set title=excluded.title,content=excluded.content,resource_url=excluded.resource_url,duration_minutes=excluded.duration_minutes,is_published=true;
 insert into public.lessons(module_id,title,content,video_url,resource_url,duration_minutes,sort_order,is_published) select id,'Binary logistic regression','Use Binary Logistic Regression when the outcome has two categories. Define the event category, interpret odds ratios and confidence intervals, and assess model fit and classification cautiously, especially with imbalanced outcomes.',null,'https://www.ibm.com/docs/en/spss-statistics',25,3,true from public.course_modules where course_id=v_course and sort_order=7 on conflict(module_id,sort_order) do update set title=excluded.title,content=excluded.content,resource_url=excluded.resource_url,duration_minutes=excluded.duration_minutes,is_published=true;
 insert into public.lessons(module_id,title,content,video_url,resource_url,duration_minutes,sort_order,is_published) select id,'Interpret coefficients and communicate uncertainty','Explain coefficient direction, magnitude, units and uncertainty in plain language. Distinguish association from causal effects and avoid claiming that a predictor causes an outcome in observational data.',null,'https://www.ibm.com/docs/en/spss-statistics',25,4,true from public.course_modules where course_id=v_course and sort_order=7 on conflict(module_id,sort_order) do update set title=excluded.title,content=excluded.content,resource_url=excluded.resource_url,duration_minutes=excluded.duration_minutes,is_published=true;
 insert into public.lessons(module_id,title,content,video_url,resource_url,duration_minutes,sort_order,is_published) select id,'Choose and justify an appropriate model','Match the outcome type and study question to a suitable model. Document inclusion criteria, missing-data handling, assumptions, diagnostics and limitations so another analyst can review the decisions.',null,'https://www.ibm.com/docs/en/spss-statistics',30,5,true from public.course_modules where course_id=v_course and sort_order=7 on conflict(module_id,sort_order) do update set title=excluded.title,content=excluded.content,resource_url=excluded.resource_url,duration_minutes=excluded.duration_minutes,is_published=true;
 insert into public.lessons(module_id,title,content,video_url,resource_url,duration_minutes,sort_order,is_published) select id,'Format tables and charts for reporting','Edit pivot tables for clear labels, consistent decimal places and readable categories. Remove redundant output and ensure chart titles, axes, legends and notes explain the analysis without overstating results.',null,'https://www.ibm.com/docs/en/spss-statistics',25,1,true from public.course_modules where course_id=v_course and sort_order=8 on conflict(module_id,sort_order) do update set title=excluded.title,content=excluded.content,resource_url=excluded.resource_url,duration_minutes=excluded.duration_minutes,is_published=true;
 insert into public.lessons(module_id,title,content,video_url,resource_url,duration_minutes,sort_order,is_published) select id,'Export output to Word, Excel and PDF','Export selected tables and charts using appropriate formats. Check page breaks, fonts, footnotes and table readability after export. Keep the native output file and syntax alongside the final report.',null,'https://www.ibm.com/docs/en/spss-statistics',25,2,true from public.course_modules where course_id=v_course and sort_order=8 on conflict(module_id,sort_order) do update set title=excluded.title,content=excluded.content,resource_url=excluded.resource_url,duration_minutes=excluded.duration_minutes,is_published=true;
 insert into public.lessons(module_id,title,content,video_url,resource_url,duration_minutes,sort_order,is_published) select id,'Build a reproducible syntax workflow','Use syntax for imports, recoding, descriptive summaries and statistical tests. Add comments, organise commands into sections and rerun the complete file from a clean session to verify reproducibility.',null,'https://www.ibm.com/docs/en/spss-statistics',25,3,true from public.course_modules where course_id=v_course and sort_order=8 on conflict(module_id,sort_order) do update set title=excluded.title,content=excluded.content,resource_url=excluded.resource_url,duration_minutes=excluded.duration_minutes,is_published=true;
 insert into public.lessons(module_id,title,content,video_url,resource_url,duration_minutes,sort_order,is_published) select id,'Write methods, findings and limitations','Describe the dataset, sample, variable definitions, cleaning decisions and statistical methods. Present findings with denominators and uncertainty, acknowledge limitations and separate observed associations from recommendations.',null,'https://www.ibm.com/docs/en/spss-statistics',25,4,true from public.course_modules where course_id=v_course and sort_order=8 on conflict(module_id,sort_order) do update set title=excluded.title,content=excluded.content,resource_url=excluded.resource_url,duration_minutes=excluded.duration_minutes,is_published=true;
 insert into public.lessons(module_id,title,content,video_url,resource_url,duration_minutes,sort_order,is_published) select id,'Capstone: analyse an education survey dataset','Complete an end-to-end SPSS analysis using the supplied synthetic education dataset. Submit a cleaned .sav file, syntax, data-quality log, descriptive tables, at least two charts, one justified inferential analysis and a concise findings report.',null,'https://www.ibm.com/docs/en/spss-statistics',30,5,true from public.course_modules where course_id=v_course and sort_order=8 on conflict(module_id,sort_order) do update set title=excluded.title,content=excluded.content,resource_url=excluded.resource_url,duration_minutes=excluded.duration_minutes,is_published=true;
 insert into public.assessments(course_id,title,instructions,total_marks,is_published)
 select v_course,'SPSS Education Survey Analysis Capstone',
 'Analyse the supplied synthetic education survey dataset in SPSS. Submit: (1) a cleaned .sav dataset; (2) an SPSS syntax file covering import, cleaning and analysis; (3) a data-quality log; (4) descriptive tables and at least two labelled charts; (5) one justified inferential test with assumptions and interpretation; and (6) a 700–1,000 word findings report covering methods, results, limitations and recommendations. Do not infer causation from observational data.',
 100,false
 where not exists(select 1 from public.assessments a where a.course_id=v_course and a.title='SPSS Education Survey Analysis Capstone');
 insert into public.quizzes(course_id,title,description,pass_mark,is_published,sort_order)
 select v_course,x.title,x.description,60,true,x.sort_order from (values
 ('SPSS Foundations Checkpoint','Check SPSS interface, cases, variables, measurement levels and data import.',1),
 ('SPSS Data Cleaning and Descriptives Checkpoint','Review missing data, duplicates, recoding, frequencies and descriptive statistics.',2),
 ('SPSS Inferential Statistics Checkpoint','Assess test selection, assumptions, regression and responsible interpretation.',3)
 ) x(title,description,sort_order)
 where not exists(select 1 from public.quizzes q where q.course_id=v_course and q.title=x.title);
   insert into public.quiz_questions(quiz_id,question_text,options,sort_order)
  select q.id,x.question_text,x.options::jsonb,x.sort_order from public.quizzes q join (values
   ('SPSS Foundations Checkpoint','In SPSS, what does one row usually represent?','["A variable","A case or observation","A chart","A syntax command"]',1,1),
   ('SPSS Foundations Checkpoint','Where are variable labels and value labels defined?','["Output Viewer","Variable View","Chart Editor","Syntax window"]',2,1),
   ('SPSS Foundations Checkpoint','Which measurement level describes unordered categories?','["Scale","Ordinal","Nominal","Interval only"]',3,2),
   ('SPSS Foundations Checkpoint','What is the main benefit of saving SPSS syntax?','["It hides missing values","It makes analysis steps reviewable and repeatable","It automatically proves hypotheses","It replaces the dataset"]',4,1),
   ('SPSS Foundations Checkpoint','Before analysing an imported CSV, what should you check?','["Only the file name","Row count, headers, delimiters and variable types","Only the first row","Only the font"]',5,1)
  ) x(quiz_title,question_text,options,sort_order,correct_option) on q.title=x.quiz_title and q.course_id=v_course
  where not exists(select 1 from public.quiz_questions z where z.quiz_id=q.id and z.sort_order=x.sort_order);
  insert into public.quiz_answer_keys(question_id,correct_option)
  select qq.id,x.correct_option from public.quiz_questions qq join public.quizzes q on q.id=qq.quiz_id join (values
   ('SPSS Foundations Checkpoint',1,1),
   ('SPSS Foundations Checkpoint',2,1),
   ('SPSS Foundations Checkpoint',3,2),
   ('SPSS Foundations Checkpoint',4,1),
   ('SPSS Foundations Checkpoint',5,1)
  ) x(quiz_title,sort_order,correct_option) on q.title=x.quiz_title and q.course_id=v_course and qq.sort_order=x.sort_order
  on conflict(question_id) do nothing;

  insert into public.quiz_questions(quiz_id,question_text,options,sort_order)
  select q.id,x.question_text,x.options::jsonb,x.sort_order from public.quizzes q join (values
   ('SPSS Data Cleaning and Descriptives Checkpoint','What should you do before replacing missing values with zero?','["Replace all blanks immediately","Investigate what missing means in the study","Delete the variable","Convert all values to text"]',1,1),
   ('SPSS Data Cleaning and Descriptives Checkpoint','Which SPSS tool can identify duplicate cases?','["Identify Duplicate Cases","Chart Builder","One-Sample T Test","Compute Mean"]',2,0),
   ('SPSS Data Cleaning and Descriptives Checkpoint','Which procedure is commonly used for categorical frequency summaries?','["Linear Regression","Frequencies","Paired T Test","Reliability only"]',3,1),
   ('SPSS Data Cleaning and Descriptives Checkpoint','Why recode into a different variable?','["To preserve the original values for audit","To remove the data dictionary","To change the sample size automatically","To hide categories"]',4,0),
   ('SPSS Data Cleaning and Descriptives Checkpoint','What should you inspect when checking an attendance variable?','["Whether attendance exceeds enrolled days","Whether labels are alphabetical","Whether the file is compressed","Whether the chart is 3D"]',5,0)
  ) x(quiz_title,question_text,options,sort_order,correct_option) on q.title=x.quiz_title and q.course_id=v_course
  where not exists(select 1 from public.quiz_questions z where z.quiz_id=q.id and z.sort_order=x.sort_order);
  insert into public.quiz_answer_keys(question_id,correct_option)
  select qq.id,x.correct_option from public.quiz_questions qq join public.quizzes q on q.id=qq.quiz_id join (values
   ('SPSS Data Cleaning and Descriptives Checkpoint',1,1),
   ('SPSS Data Cleaning and Descriptives Checkpoint',2,0),
   ('SPSS Data Cleaning and Descriptives Checkpoint',3,1),
   ('SPSS Data Cleaning and Descriptives Checkpoint',4,0),
   ('SPSS Data Cleaning and Descriptives Checkpoint',5,0)
  ) x(quiz_title,sort_order,correct_option) on q.title=x.quiz_title and q.course_id=v_course and qq.sort_order=x.sort_order
  on conflict(question_id) do nothing;

  insert into public.quiz_questions(quiz_id,question_text,options,sort_order)
  select q.id,x.question_text,x.options::jsonb,x.sort_order from public.quizzes q join (values
   ('SPSS Inferential Statistics Checkpoint','Which test is often used to assess association between two categorical variables?','["Independent t-test","Chi-square test","Pearson correlation","Linear regression"]',1,1),
   ('SPSS Inferential Statistics Checkpoint','Which test compares the means of two independent groups?','["Paired t-test","Independent-samples t-test","Chi-square","Spearman correlation"]',2,1),
   ('SPSS Inferential Statistics Checkpoint','What does a p-value alone tell you?','["The probability the null hypothesis is true","Whether the effect is practically important","Evidence relative to a specified null model under assumptions","That one variable causes another"]',3,2),
   ('SPSS Inferential Statistics Checkpoint','Which model is suited to a binary outcome?','["Binary logistic regression","One-way ANOVA","Pearson correlation","Frequency table"]',4,0),
   ('SPSS Inferential Statistics Checkpoint','What does correlation establish?','["Causation","Association, not causation","No uncertainty","A valid regression model in every case"]',5,1)
  ) x(quiz_title,question_text,options,sort_order,correct_option) on q.title=x.quiz_title and q.course_id=v_course
  where not exists(select 1 from public.quiz_questions z where z.quiz_id=q.id and z.sort_order=x.sort_order);
  insert into public.quiz_answer_keys(question_id,correct_option)
  select qq.id,x.correct_option from public.quiz_questions qq join public.quizzes q on q.id=qq.quiz_id join (values
   ('SPSS Inferential Statistics Checkpoint',1,1),
   ('SPSS Inferential Statistics Checkpoint',2,1),
   ('SPSS Inferential Statistics Checkpoint',3,2),
   ('SPSS Inferential Statistics Checkpoint',4,0),
   ('SPSS Inferential Statistics Checkpoint',5,1)
  ) x(quiz_title,sort_order,correct_option) on q.title=x.quiz_title and q.course_id=v_course and qq.sort_order=x.sort_order
  on conflict(question_id) do nothing;
end $$;

